import re
import os
import glob
import mimetypes


def task_func(directory, file_pattern, suffix):
    """
    Scan `directory` for files whose names match the regex `file_pattern`
    and end with `suffix`, and return a dict mapping each matched file name
    to its MIME type (None if the type cannot be determined).
    """
    result = {}
    if not os.path.isdir(directory):
        return result

    # Use glob to list entries with the given suffix, then filter by regex.
    search = os.path.join(glob.escape(directory), "*" + glob.escape(suffix))
    regex = re.compile(file_pattern)

    for path in sorted(glob.glob(search)):
        if not os.path.isfile(path):
            continue
        name = os.path.basename(path)
        if regex.match(name):
            mime_type, _ = mimetypes.guess_type(name)
            result[name] = mime_type

    return result


if __name__ == "__main__":
    import sys
    if len(sys.argv) == 4:
        print(task_func(sys.argv[1], sys.argv[2], sys.argv[3]))
    else:
        print("Usage: python script.py <directory> <file_pattern_regex> <suffix>")

from collections import Counter
import itertools


def task_func(d):
    """
    Count how many times each integer appears across all list values of a dictionary.

    Parameters:
        d (dict): A dictionary whose values are lists of integers.

    Returns:
        dict: A dictionary mapping each integer found in any of the lists to the
              total number of times it appears across all lists combined.
    """
    # Flatten all list values into one iterable, then count the occurrences
    all_values = itertools.chain.from_iterable(d.values())
    return dict(Counter(all_values))


if __name__ == "__main__":
    # Example usage
    sample = {"a": [1, 2, 3, 1], "b": [3, 4, 5], "c": [1, 2]}
    print(task_func(sample))  # {1: 3, 2: 2, 3: 2, 4: 1, 5: 1}
    print(task_func({}))      # {}

