    Find the most recently modified file in log_dir whose name matches
    the given regex pattern.

    Returns:
        str or None: Path to the latest matching file, or None if there is none.
    """
    try:
        entries = os.listdir(log_dir)
    except (FileNotFoundError, NotADirectoryError, PermissionError):
        return None

    try:
        regex = re.compile(pattern)
    except re.error:
        return None

    latest_path = None
    latest_mtime = None

    for name in entries:
        if not regex.match(name):
            continue
        path = os.path.join(log_dir, name)
        if not os.path.isfile(path):
            continue
        try:
            mtime = os.path.getmtime(path)
        except OSError:
            continue
        if latest_mtime is None or mtime > latest_mtime:
            latest_mtime = mtime
            latest_path = path

    return latest_path

